/* Handle a request: look up the session, refresh it, build a reply. */
struct session *sess = find_session(id);
if (sess == NULL)
    return -1;

if (sess->expired) {
    free_session(sess);          /* frees sess and unlinks it from the table */
}

/* Refresh last-seen time and build the response. */
sess->last_seen = now();
snprintf(out, len, "welcome %s", sess->user);
return 0;

